    QApplicationHandle quick_app = QApplicationCreate(&app_info);

    QApplicationStart(quick_app);
    uv_run(&loop, UV_RUN_DEFAULT);

    MessageLoop_Destroy(ui_message_loop);

    GUILoopStop(gui_loop_data);

    vg_deinit();
    lv_deinit();
    GUIWidgetUninit();

    return 0;
}
