+<script>
+import smartHome from '@system.smarthome'
+
+const DEVICE_ID = 'sim-living-room-light'
+
+function readLight(snapshot) {
+  const devices = snapshot && snapshot.devices ? snapshot.devices : []
+  for (let index = 0; index < devices.length; index += 1) {
+    if (devices[index].id === DEVICE_ID) {
+      return devices[index]
+    }
+  }
+  return null
+}
+
+function errorText(error) {
+  if (!error) {
+    return 'SmartHome 服务不可用'
+  }
+  if (error.message) {
+    return error.message
+  }
+  return String(error)
+}
+
+export default {
+  data: {
+    deviceId: DEVICE_ID,
+    serviceLabel: '正在连接',
+    onlineLabel: '等待状态',
+    onlineColor: '#8a938b',
+    power: false,
+    powerLabel: '--',
+    brightness: '--',
+    commandLabel: '正在读取原生状态',
+    revision: 0,
+    revisionLabel: '--',
+    updatedLabel: '--',
+    errorMessage: '',
+    requestPending: false,
+    unsubscribe: null
+  },
+
+  onInit() {
+    this.connect()
+  },
+
+  onDestroy() {
+    this.detachSubscription()
+  },
+
+  async connect() {
+    this.serviceLabel = '正在连接'
+    this.errorMessage = ''
+
+    try {
+      await smartHome.getCapabilities()
+      const snapshot = await smartHome.getSnapshot()
+      this.applySnapshot(snapshot)
+      this.attachSubscription()
+      this.serviceLabel = '服务已连接'
+    } catch (error) {
+      this.serviceLabel = '服务不可用'
+      this.commandLabel = '无法读取原生状态'
+      this.errorMessage = errorText(error)
+    }
+  },
+
+  attachSubscription() {
+    this.detachSubscription()
+    this.unsubscribe = smartHome.subscribeState((event) => {
+      if (!event || !event.snapshot) {
+        return
+      }
+      if (event.revision > this.revision + 1) {
+        this.connect()
+        return
+      }
+      this.applySnapshot(event.snapshot)
+    })
+  },
+
+  detachSubscription() {
+    if (typeof this.unsubscribe === 'function') {
+      this.unsubscribe()
+    }
+    this.unsubscribe = null
+  },
+
+  applySnapshot(snapshot) {
+    const light = readLight(snapshot)
+    if (!light) {
+      this.errorMessage = '原生状态中未找到客厅主灯'
+      return
+    }
+
+    this.power = Boolean(light.power)
+    this.powerLabel = this.power ? '已开启' : '已关闭'
+    this.brightness = light.brightness
+    this.onlineLabel = light.online ? '在线' : '离线'
+    this.onlineColor = light.online ? '#4d8f7a' : '#bf725d'
+    this.revision = snapshot.revision
+    this.revisionLabel = `r${snapshot.revision}`
+    this.updatedLabel = '刚刚'
+    this.commandLabel = this.requestPending ? '等待原生服务确认' : '状态来自原生服务'
+    this.errorMessage = ''
+  },
+
+  async togglePower() {
+    if (this.requestPending || this.onlineLabel !== '在线') {
+      return
+    }
+
+    this.requestPending = true
+    this.commandLabel = '正在请求原生服务'
+    this.errorMessage = ''
+
+    try {
+      await smartHome.controlDevice({
+        requestId: `ui-${Date.now()}-${this.revision}`,
+        deviceId: DEVICE_ID,
+        command: 'setPower',
+        value: !this.power,
+        expectedRevision: this.revision
+      })
+      this.commandLabel = '等待原生服务确认'
+    } catch (error) {
+      this.commandLabel = '控制请求被拒绝'
+      this.errorMessage = errorText(error)
+    } finally {
+      this.requestPending = false
+    }
+  }
+}
