<script>
import smartHome from '@system.smarthome'

const DEVICE_ID = 'sim-living-room-light'

function errorText(error) {
  if (!error) {
    return 'SmartHome 服务不可用'
  }
  if (error.message) {
    return error.message
  }
  return String(error)
}

export default {
  data: {
    deviceId: DEVICE_ID,
    serviceLabel: '正在连接',
    onlineLabel: '等待状态',
    onlineColor: '#8a938b',
    power: false,
    powerLabel: '--',
    brightness: '--',
    commandLabel: '正在读取原生状态',
    revision: 0,
    revisionLabel: '--',
    updatedLabel: '--',
    errorMessage: '',
    requestPending: false
  },

  onInit() {
    this.connect()
  },

  async connect() {
    this.serviceLabel = '正在连接'
    this.errorMessage = ''

    try {
      const capabilities = await smartHome.getCapabilities()
      const devices = capabilities && capabilities.devices ? capabilities.devices : []
      const light = devices.find((device) => device.deviceId === DEVICE_ID)
      if (!light || !light.commands || !light.commands.includes('setPower')) {
        throw new Error('原生服务未声明客厅主灯的开关能力')
      }
      await this.refreshSnapshot()
      this.serviceLabel = '服务已连接'
    } catch (error) {
      this.serviceLabel = '服务不可用'
      this.commandLabel = '无法读取原生状态'
      this.errorMessage = errorText(error)
    }
  },

  async refreshSnapshot() {
    const snapshot = await smartHome.getSnapshot({ deviceId: DEVICE_ID })
    this.applySnapshot(snapshot)
  },

  applySnapshot(snapshot) {
    if (!snapshot || snapshot.deviceId !== DEVICE_ID) {
      this.errorMessage = '原生状态中未找到客厅主灯'
      return
    }

    this.power = Boolean(snapshot.power)
    this.powerLabel = this.power ? '已开启' : '已关闭'
    this.brightness = snapshot.brightness
    this.onlineLabel = snapshot.online ? '在线' : '离线'
    this.onlineColor = snapshot.online ? '#4d8f7a' : '#bf725d'
    this.revision = snapshot.revision
    this.revisionLabel = `r${snapshot.revision}`
    this.updatedLabel = '刚刚'
    this.commandLabel = this.requestPending ? '等待原生服务确认' : '状态来自原生服务'
    this.errorMessage = ''
  },

  async togglePower() {
    if (this.requestPending || this.onlineLabel !== '在线') {
      return
    }

    this.requestPending = true
    this.commandLabel = '正在请求原生服务'
    this.errorMessage = ''

    try {
      const result = await smartHome.controlDevice({
        requestId: `ui-${Date.now()}-${this.revision}`,
        deviceId: DEVICE_ID,
        command: 'setPower',
        value: !this.power,
        expectedRevision: this.revision
      })
      if (!result || !result.applied || !result.snapshot) {
        throw new Error('原生服务未确认控制结果')
