static char *smart_home_strdup(const char *src)
{
  if (src == nullptr)
    {
      return nullptr;
    }

  size_t len = std::strlen(src);
  char *copy = static_cast<char *>(FeatureMalloc(len + 1, FT_STRING));
  if (copy != nullptr)
    {
      std::memcpy(copy, src, len);
      copy[len] = '\0';
    }

  return copy;
}

static system_smarthome_DeviceSnapshot *smart_home_make_snapshot(
  const struct smart_home_quickapp_bridge_snapshot_s *snapshot)
{
  system_smarthome_DeviceSnapshot *result =
    system_smarthomeMallocDeviceSnapshot();
  if (result == nullptr)
    {
      return nullptr;
    }

  result->deviceId = smart_home_strdup(snapshot->device_id);
  result->revision = static_cast<FtInt>(snapshot->revision);
  result->online = snapshot->online;
  result->power = snapshot->power;
  result->brightness = static_cast<FtInt>(snapshot->brightness);
  return result;
}

