#define SH_ERR_STALE 1002
#define SH_ERR_BUSY 1003
#define SH_IPC_MAX_MESSAGES 4

struct Pending {
  FeatureInstanceHandle feature;
  FtPromiseId pid;
  uint16_t operation;
};

struct Context {
  uv_async_queue_t async_queue;
  mqd_t response_queue;
  pthread_t receiver;
  bool initialized;
  bool running;
  bool receiver_started;
  std::mutex mutex;
  std::map<std::string, Pending> pending;
};

static std::atomic<uint32_t> g_sequence{0};

static char *sh_strdup(const char *src)
{
  if (!src) return nullptr;
  size_t len = std::strlen(src);
  char *copy = static_cast<char *>(FeatureMalloc(len + 1, FT_STRING));
  if (copy) { std::memcpy(copy, src, len); copy[len] = '\0'; }
  return copy;
}

static void sh_copy(char *dest, size_t size, const char *src)
{
  if (!dest || size == 0) return;
  if (!src) { dest[0] = '\0'; return; }
  std::strncpy(dest, src, size - 1);
  dest[size - 1] = '\0';
}

static int sh_error(int status)
{
  if (status == SMART_HOME_QUICKAPP_IPC_STATUS_STALE) return SH_ERR_STALE;
  if (status == SMART_HOME_QUICKAPP_IPC_STATUS_INVALID) return SH_ERR_INVALID;
  return SH_ERR_UNAVAILABLE;
}

static system_smarthome_DeviceSnapshot *sh_snapshot(
  const smart_home_quickapp_ipc_response_s *reply)
{
  auto *snapshot = system_smarthomeMallocDeviceSnapshot();
  if (!snapshot) return nullptr;
  snapshot->deviceId = sh_strdup(reply->device_id);
  snapshot->revision = static_cast<FtInt>(reply->revision);
  snapshot->online = reply->online != 0;
  snapshot->power = reply->power != 0;
  snapshot->brightness = static_cast<FtInt>(reply->brightness);
  return snapshot;
}

static void sh_resolve_capabilities(FeatureInstanceHandle feature, FtPromiseId pid,
  const smart_home_quickapp_ipc_response_s *reply)
{
  auto *response = system_smarthomeMallocCapabilitiesResponse();
  auto *device = system_smarthomeMallocDeviceCapability();
  char *command = nullptr;
  if (!response || !device) goto fail;
  response->apiVersion = static_cast<FtInt>(reply->api_version);
  response->devices = system_smarthome_malloc_DeviceCapability_struct_type_array();
  device->deviceId = sh_strdup(reply->device_id);
  device->type = sh_strdup(reply->type);
  device->commands = system_smarthome_malloc_string_array();
  command = sh_strdup(reply->command);
  if (!response->devices || !device->deviceId || !device->type ||
      !device->commands || !command || !FeatureArrayAppend(device->commands, command) ||
      !FeatureArrayAppend(response->devices, device)) {
    FeatureFreeValue(command);
    goto fail;
  }
  FeatureFreeValue(command);
  FeatureFreeValue(device);
  system_smarthome_CapabilitiesResponse_ptr_promise_resolve(feature, pid, response);
  FeatureFreeValue(response);
  return;
fail:
  FeatureFreeValue(response);
  FeatureFreeValue(device);
  FeaturePromiseReject(feature, pid, SH_ERR_UNAVAILABLE,
                       "Unable to allocate SmartHome capabilities");
}

static void sh_resolve_snapshot(FeatureInstanceHandle feature, FtPromiseId pid,
  const smart_home_quickapp_ipc_response_s *reply)
{
  auto *snapshot = sh_snapshot(reply);
  if (!snapshot || !snapshot->deviceId) {
    FeatureFreeValue(snapshot);
    FeaturePromiseReject(feature, pid, SH_ERR_UNAVAILABLE,
                         "Unable to allocate SmartHome state");
    return;
  }
  system_smarthome_DeviceSnapshot_ptr_promise_resolve(feature, pid, snapshot);
  FeatureFreeValue(snapshot);
}

static void sh_resolve_control(FeatureInstanceHandle feature, FtPromiseId pid,
  const smart_home_quickapp_ipc_response_s *reply)
{
  auto *response = system_smarthomeMallocControlResponse();
  if (!response) goto fail;
  response->applied = true;
  response->snapshot = sh_snapshot(reply);
  if (!response->snapshot || !response->snapshot->deviceId) goto fail;
  system_smarthome_ControlResponse_ptr_promise_resolve(feature, pid, response);
  FeatureFreeValue(response);
  return;
fail:
  FeatureFreeValue(response);
  FeaturePromiseReject(feature, pid, SH_ERR_UNAVAILABLE,
                       "Unable to allocate SmartHome control result");
}

static void sh_async_response(uv_async_queue_t *queue, void *data)
{
  auto *context = static_cast<Context *>(queue->data);
  auto *reply = static_cast<smart_home_quickapp_ipc_response_s *>(data);
  Pending pending = {};
  bool found = false;
  if (!context || !reply || reply->magic != SMART_HOME_QUICKAPP_IPC_MAGIC ||
      reply->version != SMART_HOME_QUICKAPP_IPC_VERSION || !reply->request_id[0]) {
    free(reply); return;
  }
  {
    std::lock_guard<std::mutex> lock(context->mutex);
    auto it = context->pending.find(reply->request_id);
    if (it != context->pending.end()) { pending = it->second; context->pending.erase(it); found = true; }
  }
  if (found && !FeatureInstanceIsDetached(pending.feature)) {
    if (reply->status != SMART_HOME_QUICKAPP_IPC_STATUS_OK) {
      FeaturePromiseReject(pending.feature, pending.pid, sh_error(reply->status),
        reply->status == SMART_HOME_QUICKAPP_IPC_STATUS_STALE ?
        "SmartHome state is stale" : "SmartHome service rejected the request");
    } else if (pending.operation == SMART_HOME_QUICKAPP_IPC_GET_CAPABILITIES) {
      sh_resolve_capabilities(pending.feature, pending.pid, reply);
    } else if (pending.operation == SMART_HOME_QUICKAPP_IPC_GET_SNAPSHOT) {
      sh_resolve_snapshot(pending.feature, pending.pid, reply);
    } else if (pending.operation == SMART_HOME_QUICKAPP_IPC_CONTROL_DEVICE) {
      sh_resolve_control(pending.feature, pending.pid, reply);
    }
  }
  if (found) FeatureFreeInstanceHandle(pending.feature);
  free(reply);
}

static void *sh_receiver(void *arg)
{
  auto *context = static_cast<Context *>(arg);
  while (context->running) {
    auto *reply = static_cast<smart_home_quickapp_ipc_response_s *>(
      malloc(sizeof(smart_home_quickapp_ipc_response_s)));
    if (!reply) break;
    ssize_t count = mq_receive(context->response_queue, reinterpret_cast<char *>(reply),
                               sizeof(*reply), nullptr);
    if (count < 0) { free(reply); if (errno == EINTR) continue; break; }
    if (static_cast<size_t>(count) != sizeof(*reply)) { free(reply); continue; }
    if (context->initialized) uv_async_queue_send(&context->async_queue, reply);
    else free(reply);
  }
  return nullptr;
}

static bool sh_send(Context *context, FeatureInstanceHandle feature, FtPromiseId pid,
                    smart_home_quickapp_ipc_request_s *request)
{
  mqd_t queue = mq_open(SMART_HOME_QUICKAPP_IPC_REQUEST_QUEUE, O_WRONLY | O_NONBLOCK);
  if (queue == static_cast<mqd_t>(-1)) {
    FeaturePromiseReject(feature, pid, SH_ERR_UNAVAILABLE, "SmartHome service is unavailable");
    return false;
  }
  Pending pending = { FeatureDupInstanceHandle(feature), pid, request->operation };
  {
    std::lock_guard<std::mutex> lock(context->mutex);
    if (context->pending.find(request->request_id) != context->pending.end()) {
      mq_close(queue); FeatureFreeInstanceHandle(pending.feature);
      FeaturePromiseReject(feature, pid, SH_ERR_BUSY, "A SmartHome request is pending");
      return false;
    }
    context->pending[request->request_id] = pending;
  }
  if (mq_send(queue, reinterpret_cast<const char *>(request), sizeof(*request), 0) == 0) {
    mq_close(queue); return true;
  }
  {
    std::lock_guard<std::mutex> lock(context->mutex);
    context->pending.erase(request->request_id);
  }
  mq_close(queue);
  FeatureFreeInstanceHandle(pending.feature);
  FeaturePromiseReject(feature, pid, SH_ERR_UNAVAILABLE, "SmartHome service is unavailable");
  return false;
}

static bool sh_generated_id(char *id, size_t size, const char *prefix)
{
  int count = std::snprintf(id, size, "%s-%lu", prefix,
    static_cast<unsigned long>(g_sequence.fetch_add(1)));
  return count > 0 && static_cast<size_t>(count) < size;
}

void system_smarthome_onRegister(const char *feature_name) { FEATURE_LOG_INFO("[smarthome] onRegister: %s", feature_name); }

void system_smarthome_onCreate(FeatureRuntimeContext ctx, FeatureProtoHandle handle)
{
  mq_attr attr = { .mq_maxmsg = SH_IPC_MAX_MESSAGES,
                   .mq_msgsize = sizeof(smart_home_quickapp_ipc_response_s) };
  auto *context = new Context();
  if (!context) return;
  context->initialized = false; context->running = false; context->receiver_started = false;
  context->response_queue = mq_open(SMART_HOME_QUICKAPP_IPC_RESPONSE_QUEUE,
                                    O_RDONLY | O_CREAT, 0660, &attr);
  if (context->response_queue == static_cast<mqd_t>(-1)) { delete context; return; }
  context->async_queue.data = context;
  FeatureManagerHandle manager = FeatureGetManagerHandleFromProto(handle);
  if (uv_async_queue_init(FeatureGetUVLoop(manager), &context->async_queue, sh_async_response) != 0) {
    mq_close(context->response_queue); delete context; return;
  }
  context->initialized = true; context->running = true;
  if (pthread_create(&context->receiver, nullptr, sh_receiver, context) != 0) {
    context->running = false; context->initialized = false;
    mq_close(context->response_queue); delete context; return;
  }
  context->receiver_started = true;
  FeatureSetProtoData(handle, context);
}

