        lv_obj_del(ui->screen_chat);
    }
    if (ui->screen_settings) {
        lv_obj_del(ui->screen_settings);
    }

    pthread_mutex_destroy(&ui->pending_mutex);
    smart_home_bulk_free(ui->agent_worker_stack_alloc);
    free(ui);
