:root {
  --ui-canvas: #f4f2ee;
  --ui-surface: #fbfaf8;
  --ui-card: #ffffff;
  --ui-card-hover: #f8f7f4;
  --ui-text: #26312e;
  --ui-subtext: #74807b;
  --ui-line: #e5e1da;
  --ui-active: #e6f0ea;
  --ui-active-text: #286a4b;
  --ui-shadow: 0 5px 18px rgba(72, 67, 55, .07);
  --ui-radius-card: 17px;
  --ui-radius-control: 11px;
  --ui-weather: #e9f3f4;
  --ui-comfort: #faebe3;
  --ui-safe: #eaf2eb;
  --ui-service: #f1edf8;
}

body { background: radial-gradient(circle at 50% 0, #fff 0, var(--ui-canvas) 58%, #ece9e3 100%); }
.panel { background: var(--ui-canvas); border-color: #e2ded7; box-shadow: 0 28px 80px rgba(74, 68, 55, .17); }
.topbar { background: rgba(251, 250, 248, .94); border-color: var(--ui-line); }
.brand { color: var(--ui-text); }.brand b { color: #527866; }
.eyebrow, .page-hint { color: var(--ui-subtext); }
.page-header h1, .device-card b, .more-card b { color: var(--ui-text); }

/* 容器统一采用轻边框、同一圆角和弱阴影；功能色仅作为低饱和背景。 */
.board-tile, .device-card, .scene-page-card, .more-card, .monitor-card, .alert-card,
.quick-control, .device-primary { border: 1px solid var(--ui-line); border-radius: var(--ui-radius-card); box-shadow: var(--ui-shadow); }
.board-tile:hover, .device-card:hover, .scene-page-card:hover, .more-card:hover,
.quick-control:hover { filter: none; background-color: var(--ui-card-hover); transform: translateY(-1px); }
.weather-tile { color: var(--ui-text); background: radial-gradient(circle at 82% 16%, #bddce455 0, transparent 35%), var(--ui-weather); }
.scene-slot .scene-card { color: #503d35; background: #f9eee8; }.scene-slot .scene-card:before { opacity: .25; }
.ac-tile { color: #503e35; background: radial-gradient(circle at 82% 12%, #e7a88755 0, transparent 40%), var(--ui-comfort); }
.camera-tile { color: #29413b; background: linear-gradient(135deg, #edf4f1, #ddeae5); }
.agent-tile { color: #4a3e59; background: radial-gradient(circle at 62% 74%, #c6b5df55 0, transparent 27%), var(--ui-service); }
.music-tile { color: #503e35; background: #f8eee8; }
.status-tile { color: #30483d; background: var(--ui-safe); }
.tile-title small, .camera-room small, .music-tile small, .agent-tile small { color: #78675e; }

.device-card, .scene-page-card, .more-card, .quick-control { background: var(--ui-card); }
.device-card small, .more-card small { color: var(--ui-subtext); }
.filter, .outline-button, .detail-option { border-color: var(--ui-line); background: var(--ui-surface); color: #5c6762; }
.filter.active, .detail-option.active { background: var(--ui-active); border-color: #b6d2c0; color: var(--ui-active-text); }
.outline-button:hover { background: var(--ui-active); border-color: #b6d2c0; color: var(--ui-active-text); }
.toggle.on { background: #68aa82; }.tile-power { background: #d68459; }

.bottom-nav { background: rgba(251, 250, 248, .97); border-color: var(--ui-line); }
.nav-item { color: #77817d; }.nav-item.active { background: var(--ui-active); color: var(--ui-active-text); }
.nav-item:not(.active):hover { background: #f0efeb; }

/* 详情抽屉延续同一控制语言，避免另起一套“设置页”视觉。 */
.device-sheet { color: var(--ui-text); background: var(--ui-surface); border-color: var(--ui-line); box-shadow: -18px 0 45px rgba(73, 68, 55, .11); }
.device-primary { background: linear-gradient(135deg, #f5f3ef, #eeeae4); }
.detail-option { box-shadow: none; }.detail-row { border-color: #e9e5df; color: #66716c; }
.device-favorite { color: #b67b43; }.detail-slider { accent-color: #57916e; }
.agent-sheet { color: var(--ui-text); background: var(--ui-surface); border-color: var(--ui-line); box-shadow: var(--ui-shadow); }
.agent-suggestions button, .agent-answer { background: #ece8f5; color: #4b4665; }

/* 摄像头预览是内容画面，而不是页面主题；外围控制保持浅色。 */
.monitor-card, .alert-card { background: var(--ui-card); }
.monitor-art, .camera-preview-placeholder { box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .14); }
.toast { background: var(--ui-surface); color: #2d6248; border-color: #cce0d3; box-shadow: var(--ui-shadow); }
.page[data-page="home"] { padding-top: 14px; }
.home-board { height: 390px; display: grid; grid-template-columns: 210px 150px 360px 218px; grid-template-rows: 190px 190px; gap: 10px; }
.board-tile { position: relative; overflow: hidden; border: 0; border-radius: 17px; padding: 15px; text-align: left; color: var(--text); background: var(--card); }
.board-tile:hover { filter: brightness(1.08); }
.weather-tile { grid-row: span 2; padding: 18px; background: radial-gradient(circle at 80% 20%, #5c646455 0, transparent 34%), linear-gradient(160deg, #282e2e, #1d2122 58%, #151718); }
.weather-tile time { margin-top: 3px; font-size: 31px; }.weather-symbol { display: block; margin: 29px auto 2px; font-size: 71px; text-align: center; color: #d4e2e4; text-shadow: 0 12px 28px #88b4d633; }.weather-main { margin: 0; font-size: 45px; line-height: 1; letter-spacing: -2px; }.weather-copy { margin: 3px 0; font-size: 13px; }.weather-footer { position: absolute; bottom: 18px; left: 18px; right: 18px; display: flex; flex-wrap: wrap; gap: 11px; color: #d0d8d5; font-size: 11px; }.weather-footer small { width: 100%; color: var(--muted); font-size: 10px; }
.scene-slot { padding: 0; }.scene-slot .scene-card { width: 100%; height: 100%; padding: 16px; border-radius: 17px; }.scene-slot .scene-card:before { background: radial-gradient(circle at 66% 30%, var(--scene-color), transparent 52%), linear-gradient(145deg, #5d3230, #2e2323); }.scene-slot .scene-icon { margin-top: 41px; font-size: 26px; }.scene-slot .scene-card b { font-size: 15px; }.scene-slot .scene-card small { font-size: 10px; }
.ac-tile { display: flex; flex-direction: column; background: radial-gradient(circle at 80% 14%, #bc6a5266, transparent 42%), linear-gradient(135deg, #79453d, #4b2c29); }.ac-tile > div:first-child { display: flex; align-items: center; gap: 9px; }.tile-icon { display: grid; place-items: center; width: 38px; height: 31px; border-radius: 7px; background: #a9e1e12b; color: #c5f3ee; font-size: 23px; }.tile-title { font-size: 15px; font-weight: 700; }.tile-title small, .camera-room small, .music-tile small { display: block; margin-top: 3px; color: #f1d9d1a8; font-size: 11px; font-weight: 400; }.tile-power { position: absolute; top: 17px; right: 17px; width: 32px; height: 32px; background: #ee9362; }.tile-power:after { width: 12px; height: 12px; top: 10px; left: 10px; background: #fff3e8; }.temperature-control { display: flex; align-items: center; justify-content: space-between; margin: auto 1px 15px; }.temperature-control button { width: 43px; height: 43px; border-radius: 50%; background: #ffffff16; font-size: 29px; line-height: 1; }.temperature-control b { font-size: 42px; font-weight: 500; letter-spacing: -2px; }
.camera-tile { background: linear-gradient(135deg, #303638, #171b1d 68%); }.camera-tile:before { content: ""; position: absolute; inset: 0; background: repeating-linear-gradient(125deg, transparent 0 29px, #ffffff0c 30px 31px); }.camera-tile > span { position: absolute; z-index: 1; }.camera-tile .camera-live { top: 14px; right: 14px; color: #a9e6c0; font-size: 10px; }.camera-room { left: 15px; bottom: 35px; font-size: 15px; font-weight: 700; }.camera-enter { left: 15px; bottom: 15px; color: #d2e5df; font-size: 10px; }
.agent-tile { display: flex; flex-direction: column; align-items: flex-start; background: radial-gradient(circle at 60% 74%, #ff5a17cc 0, #ff9b3c55 12%, transparent 25%), linear-gradient(145deg, #714039, #452b29); font-size: 15px; }.agent-tile i { display: grid; place-items: center; width: 42px; height: 42px; margin: auto; border-radius: 50%; background: linear-gradient(135deg, #ffad55, #f4491f); box-shadow: 0 0 22px #ff6f3b; font-size: 22px; font-style: normal; }.agent-tile small { color: #f3d7ccbb; font-size: 10px; }
.music-tile { display: flex; align-items: flex-start; gap: 14px; background: radial-gradient(circle at 83% 18%, #cf805c55, transparent 34%), linear-gradient(135deg, #723e34, #492a27); }.record { display: grid; place-items: center; width: 50px; height: 50px; border-radius: 50%; background: repeating-radial-gradient(circle, #1a191a 0 4px, #313033 5px 6px); color: #f7af72; font-size: 18px; }.music-tile p { margin: 3px 0; }.music-tile p b { font-size: 21px; font-weight: 500; }.music-controls { position: absolute; bottom: 20px; left: 76px; display: flex; gap: 38px; }.music-controls i { font-size: 19px; font-style: normal; }
.status-tile { display: flex; flex-direction: column; align-items: flex-start; background: linear-gradient(145deg, #3c4040, #232728); }.status-tile b { margin-top: auto; font-size: 16px; }.status-tile span { margin-top: 5px; color: #b8d9c8; font-size: 11px; }.status-tile small { margin-top: auto; color: var(--muted); font-size: 10px; }
.quick-bar { display: none; }
.topbar { padding: 0 28px; }
.top-status { gap: 16px; color: #edf2ef; }
.status-glyph { display: grid; width: 18px; height: 18px; place-items: center; color: #e7ece8; }
.status-glyph svg { width: 17px; height: 17px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.status-glyph.dnd { font-size: 22px; line-height: 1; transform: rotate(-24deg); }
.wifi-status { display: flex; align-items: end; gap: 2px; width: 21px; height: 17px; padding-bottom: 1px; }
.wifi-status i { display: block; width: 4px; border-radius: 3px 3px 1px 1px; background: #edf2ef; }
.wifi-status i:nth-child(1) { height: 6px; opacity: .65; }
.wifi-status i:nth-child(2) { height: 10px; opacity: .82; }
.wifi-status i:nth-child(3) { height: 14px; }
.top-clock { display: block; font-size: 22px; font-weight: 500; line-height: 1; letter-spacing: .2px; }
.device-grid { grid-template-columns: repeat(4, 1fr); }
.device-filters { overflow: hidden; }
.filter { min-width: 56px; }

/* 一级导航是常驻触控区，保持比卡片内快捷控件更明确的尺寸与层级。 */
.bottom-nav { height: 64px; gap: 24px; align-items: center; padding: 4px 0; }
.nav-item { width: 70px; height: 56px; justify-content: center; gap: 4px; padding: 6px 4px; border-radius: 13px; transition: background .18s ease, color .18s ease; }
.nav-item img { width: 21px; height: 21px; }
.nav-item.active { background: #e6f0ea; color: #286a4b; font-weight: 650; }
.nav-item:not(.active):hover { background: #f0efeb; }
