            continue;
        }
        if (!device_matches_filter(ui, device)) {
            continue;
        }

        ui->device_cards[slot] =
            create_device_card(ui->panel_grid, ui, slot, device);
    }

#ifdef CONFIG_SMART_HOME_NODE_GATEWAY
    append_online_remote_node_cards(ui);
#endif
}

