+    if (screen == ui->screen_panel) {
+        return SMART_HOME_TAB_DEVICES;
+    }
+    if (screen == ui->screen_scenes) {
+        return SMART_HOME_TAB_SCENES;
+    }
+    if (screen == ui->screen_security) {
+        return SMART_HOME_TAB_SECURITY;
+    }
