+        return SMART_HOME_TAB_MORE;
+    }
+    return SMART_HOME_TAB_HOME;
+}
+
+void smart_home_lvgl_load_tab(smart_home_lvgl_t *ui, int tab)
+{
+    lv_obj_t *screen = NULL;
+    lv_scr_load_anim_t animation;
+
+    if (!ui || tab < 0 || tab >= SMART_HOME_TAB_COUNT) {
+        return;
+    }
+
+    switch (tab) {
+    case SMART_HOME_TAB_HOME:
+        screen = ui->screen_home;
+        break;
+    case SMART_HOME_TAB_DEVICES:
+        screen = ui->screen_panel;
+        break;
+    case SMART_HOME_TAB_SCENES:
+        screen = ui->screen_scenes;
+        break;
+    case SMART_HOME_TAB_SECURITY:
+        screen = ui->screen_security;
+        break;
+    case SMART_HOME_TAB_MORE:
+        screen = ui->screen_more;
+        break;
+    default:
+        break;
+    }
+
+    if (!screen || tab == ui->active_tab) {
+        return;
+    }
+
+    animation = tab > ui->active_tab ? LV_SCR_LOAD_ANIM_MOVE_LEFT :
+                                       LV_SCR_LOAD_ANIM_MOVE_RIGHT;
