    size_t i;

    if (!dest || dest_size == 0u) {
        return;
    }

    for (i = 0; i + 1u < dest_size && input && input[i]; i++) {
        char ch = input[i];

        if (ch == '"' || ch == '\\' || (unsigned char)ch < 0x20u) {
            ch = ' ';
        }
        dest[i] = ch;
    }
