    smart_home_lvgl_t *ui;

    ui = (smart_home_lvgl_t *)calloc(1, sizeof(*ui));
    if (!ui) {
        return NULL;
    }

    ui->app = app;
    ui->device_state = app ? &app->device_state : NULL;
    ui->active_tab = SMART_HOME_TAB_HOME;

