static void page_title(lv_obj_t *card, const char *title, const char *body)
{
    lv_obj_t *label = smart_home_lvgl_label_create(card, title,
                                                    SMART_HOME_UI_COLOR_TEXT_PRIMARY,
                                                    20);
    lv_obj_align(label, LV_ALIGN_TOP_LEFT, 0, 0);
