static void env_slider_cb(lv_event_t *event)
{
    smart_home_lvgl_t *ui = (smart_home_lvgl_t *)lv_event_get_user_data(event);
    char text[32];
    int value;

    if (!ui || !ui->env_slider || !ui->env_value_label) {
