    }

    device = smart_home_device_find_by_id(state, device_id);
    if (!device) {
        return AGENT_ERROR_NOTFOUND;
    }

    memset(device, 0, sizeof(*device));
    return AGENT_OK;
}

int smart_home_device_count(const smart_home_state_t *state)
