    int i;

    if (!state) {
        return 0;
    }

    for (i = 0; i < SMART_HOME_MAX_DEVICES; i++) {
        if (state->devices[i].used) {
            count++;
        }
    }
    return count;
}

smart_home_device_t *smart_home_device_get_by_slot(smart_home_state_t *state,
                                                   int slot)
{
    int count = 0;
    int i;

    if (!state || slot < 0) {
        return NULL;
    }

    for (i = 0; i < SMART_HOME_MAX_DEVICES; i++) {
        if (!state->devices[i].used) {
            continue;
        }
        if (count == slot) {
            return &state->devices[i];
        }
        count++;
    }
    return NULL;
}

