cJSON *smart_home_device_state_to_json(const smart_home_state_t *state)
{
    cJSON *root;
    cJSON *devices;
    cJSON *rooms;
    int count;
    int i;

    if (!state) {
        return NULL;
    }

    root = cJSON_CreateObject();
    if (!root) {
        return NULL;
    }
    cJSON_AddNumberToObject(root, "version", 2);

    rooms = cJSON_AddArrayToObject(root, "rooms");
    if (!rooms) {
        cJSON_Delete(root);
        return NULL;
    }
    for (i = 0; i < state->room_count; i++) {
        cJSON *room = cJSON_CreateString(state->rooms[i]);

        if (!room) {
            cJSON_Delete(root);
            return NULL;
        }
        cJSON_AddItemToArray(rooms, room);
    }

    devices = cJSON_AddArrayToObject(root, "devices");
    if (!devices) {
        cJSON_Delete(root);
        return NULL;
    }

    count = smart_home_device_count(state);
    for (i = 0; i < count; i++) {
        const smart_home_device_t *device =
            smart_home_device_get_const_by_slot(state, i);
        cJSON *item;

        if (!device) {
            continue;
        }
        item = cJSON_CreateObject();
        if (!item) {
            cJSON_Delete(root);
            return NULL;
        }
        cJSON_AddNumberToObject(item, "id", device->id);
        cJSON_AddStringToObject(item, "room", device->room);
        cJSON_AddStringToObject(item, "name", device->name);
        cJSON_AddStringToObject(item, "type",
                                smart_home_device_type_name(device->type));
        cJSON_AddBoolToObject(item, "on", device->on ? 1 : 0);
        if (device->type == SMART_HOME_DEVICE_LIGHT) {
            cJSON_AddNumberToObject(item, "brightness", device->brightness);
        } else if (device->type == SMART_HOME_DEVICE_AC) {
            cJSON_AddNumberToObject(item, "temperature", device->temperature);
            cJSON_AddStringToObject(item, "mode",
                                    smart_home_ac_mode_name(device->ac_mode));
            cJSON_AddStringToObject(item, "fan_speed",
                                    smart_home_ac_fan_speed_name(
                                        device->ac_fan_speed));
        }
        cJSON_AddItemToArray(devices, item);
    }

    {
        cJSON *env = cJSON_CreateObject();
        if (!env) {
            cJSON_Delete(root);
            return NULL;
        }
        cJSON_AddNumberToObject(env, "temperature", state->env_temperature);
        cJSON_AddNumberToObject(env, "humidity", state->env_humidity);
        cJSON_AddNumberToObject(env, "ambient_light", state->env_light);
        cJSON_AddItemToObject(root, "environment", env);
    }

    return root;
}

int smart_home_device_state_from_json(smart_home_state_t *state,
                                      const cJSON *root)
{
    const cJSON *devices;
    const cJSON *rooms;
    const cJSON *env;
    const cJSON *item;
    smart_home_state_t tmp;

    if (!state || !root || !cJSON_IsObject(root)) {
        return AGENT_ERROR_INVALID;
    }

    devices = cJSON_GetObjectItemCaseSensitive(root, "devices");
    if (!devices || !cJSON_IsArray(devices)) {
        return ret;
    }
    publish_locked(service, event_type, event_data, &event);
    pthread_mutex_unlock(&service->mutex);
    notify_listener(service, &event);
    return AGENT_OK;
}

int smart_home_device_service_add(smart_home_device_service_t *service,
                                  const char *room, const char *name,
                                  smart_home_device_type_t type, int *device_id)
{
    char data[SMART_HOME_DEVICE_EVENT_DATA_SIZE];
    int id = 0;
    int ret;

    if (!service || !service->mutex_initialized) {
        return AGENT_ERROR_INVALID;
    }
    pthread_mutex_lock(&service->mutex);
    ret = smart_home_device_add(service->state, room, name, type, &id);
    snprintf(data, sizeof(data), "{\"deviceId\":\"%d\",\"operation\":\"added\"}", id);
    ret = commit_mutation(service, ret, "device_state_changed", data);
    if (ret == AGENT_OK && device_id) {
        *device_id = id;
    }
    return ret;
}

int smart_home_device_service_add_room(smart_home_device_service_t *service,
                                       const char *room)
{
    char data[SMART_HOME_DEVICE_EVENT_DATA_SIZE];
    int ret;

    if (!service || !room || !service->mutex_initialized) {
        return AGENT_ERROR_INVALID;
    }

    pthread_mutex_lock(&service->mutex);
    ret = smart_home_room_add(service->state, room);
    snprintf(data, sizeof(data),
             "{\"room\":\"%s\",\"operation\":\"room_added\"}", room);
    return commit_mutation(service, ret, "room_catalog_changed", data);
}

int smart_home_device_service_update_meta(smart_home_device_service_t *service,
                                          int device_id, const char *room,
                                          const char *name)
{
    char data[SMART_HOME_DEVICE_EVENT_DATA_SIZE];
    int ret;

    if (!service || !service->mutex_initialized) {
        return AGENT_ERROR_INVALID;
    }
    pthread_mutex_lock(&service->mutex);
    ret = smart_home_device_update_meta(service->state, device_id, room, name);
    snprintf(data, sizeof(data), "{\"deviceId\":\"%d\",\"operation\":\"metadata_updated\"}", device_id);
    return commit_mutation(service, ret, "device_state_changed", data);
}

