#include "smart_home_device.h"

#include <stdio.h>
#include <string.h>

static int room_is(const char *room, const char *name)
{
    return room && strcmp(room, name) == 0;
}

static int valid_room_name(const char *room)
{
    size_t i;

    if (!room || !room[0] || strlen(room) >= SMART_HOME_ROOM_NAME_SIZE) {
        return 0;
    }

    for (i = 0; room[i]; i++) {
        char ch = room[i];

        if (!((ch >= 'a' && ch <= 'z') || (ch >= '0' && ch <= '9') ||
              ch == '_')) {
            return 0;
        }
    }
    return 1;
}

static int clamp_brightness(int brightness)
{
    if (brightness < 0) {
        return 0;
    }
    if (brightness > 100) {
        return 100;
    }
    return brightness;
}

static int clamp_temperature(int temperature)
{
    if (temperature < 16) {
        return 16;
    }
    if (temperature > 30) {
        return 30;
    }
    return temperature;
}

static int clamp_env_temperature(int temperature)
{
    if (temperature < 0) {
        return 0;
    }
    if (temperature > 45) {
        return 45;
    }
    return temperature;
}

static int clamp_humidity(int humidity)
{
    if (humidity < 0) {
        return 0;
    }
    if (humidity > 100) {
        return 100;
    }
    return humidity;
}

static int clamp_ambient_light(int ambient_light)
{
    if (ambient_light < 0) {
        return 0;
    }
    if (ambient_light > 1000) {
        return 1000;
    }
    return ambient_light;
}

static int clamp_ac_mode(int mode)
{
    return (mode < 0 || mode > 4) ? 0 : mode;
}

static int clamp_ac_fan_speed(int speed)
{
    return (speed < 0 || speed > 3) ? 3 : speed;
}

static void copy_json_safe_name(char *dest,
                                size_t dest_size,
                                const char *src,
                                const char *fallback)
{
    const char *input = (src && src[0]) ? src : fallback;
    size_t i;

    if (!dest || dest_size == 0u) {
        return;
    }

    for (i = 0; i + 1u < dest_size && input && input[i]; i++) {
        char ch = input[i];

        if (ch == '"' || ch == '\\' || (unsigned char)ch < 0x20u) {
            ch = ' ';
        }
        dest[i] = ch;
    }
    dest[i] = '\0';
}

const char *smart_home_device_type_name(smart_home_device_type_t type)
{
    return type == SMART_HOME_DEVICE_AC ? "ac" : "light";
}

smart_home_device_type_t smart_home_device_type_from_index(int index)
{
    return index == 1 ? SMART_HOME_DEVICE_AC : SMART_HOME_DEVICE_LIGHT;
}

int smart_home_device_type_to_index(smart_home_device_type_t type)
{
    return type == SMART_HOME_DEVICE_AC ? 1 : 0;
}

const char *smart_home_room_from_index(int index)
{
    return index == 1 ? "bedroom" : "living_room";
}

int smart_home_room_to_index(const char *room)
{
    return room_is(room, "bedroom") ? 1 : 0;
}

int smart_home_room_count(const smart_home_state_t *state)
{
    return state && state->room_count > 0 ? state->room_count : 0;
}

const char *smart_home_room_get(const smart_home_state_t *state, int index)
{
    if (!state || index < 0 || index >= state->room_count) {
        return NULL;
    }
    return state->rooms[index];
}

int smart_home_room_index(const smart_home_state_t *state, const char *room)
{
    int i;

    if (!state || !room) {
        return -1;
    }
    for (i = 0; i < state->room_count; i++) {
        if (room_is(state->rooms[i], room)) {
            return i;
        }
    }
    return -1;
}

int smart_home_room_add(smart_home_state_t *state, const char *room)
{
    if (!state || !valid_room_name(room)) {
        return AGENT_ERROR_INVALID;
    }
    if (smart_home_room_index(state, room) >= 0) {
        return AGENT_OK;
    }
    if (state->room_count >= SMART_HOME_MAX_ROOMS) {
        return AGENT_ERROR_LIMIT;
    }
    strncpy(state->rooms[state->room_count], room,
            SMART_HOME_ROOM_NAME_SIZE - 1u);
    state->rooms[state->room_count][SMART_HOME_ROOM_NAME_SIZE - 1u] = '\0';
    state->room_count++;
    return AGENT_OK;
}

const char *smart_home_ac_mode_name(int mode)
{
    switch (mode) {
    case 0:
        return "cool";
    case 1:
        return "heat";
    case 2:
        return "dry";
    case 3:
        return "fan";
    case 4:
        return "auto";
    default:
        return "cool";
    }
}

const char *smart_home_ac_fan_speed_name(int speed)
{
    switch (speed) {
    case 0:
        return "low";
    case 1:
        return "medium";
    case 2:
        return "high";
    case 3:
        return "auto";
    default:
        return "auto";
    }
}

