static void secure_clear(void *memory, size_t size)
{
    volatile unsigned char *p = memory;

    while (p && size-- > 0u) {
        *p++ = 0u;
    }
}

static int valid_backend_id(const char *id)
{
    const unsigned char *p = (const unsigned char *)id;
    size_t length = 0u;

    if (!p || !*p) {
        return 0;
    }

    while (*p) {
        if (!((*p >= 'a' && *p <= 'z') ||
              (*p >= '0' && *p <= '9') || *p == '_' || *p == '-')) {
            return 0;
        }
        if (++length > 32u) {
            return 0;
        }
        p++;
    }

    return 1;
}

static int contains_control(const char *value)
{
    const unsigned char *p = (const unsigned char *)value;

    if (!p) {
        return 1;
    }
    while (*p) {
        if (*p < 0x20u || *p == 0x7fu) {
            return 1;
        }
        p++;
    }
    return 0;
}

static int read_secrets_file(char **out_text, size_t *out_size)
{
    FILE *file;
    long size = -1;
    char *text;

    *out_text = NULL;
    *out_size = 0u;
    file = fopen(CONFIG_SMART_HOME_MODEL_SECRETS_PATH, "rb");
    if (!file) {
        return errno == ENOENT ? AGENT_ERROR_NOTFOUND : AGENT_ERROR;
    }

    if (fseek(file, 0, SEEK_END) != 0) {
        fclose(file);
        return AGENT_ERROR;
    }
    size = ftell(file);
    if (size < 0) {
        fclose(file);
        return AGENT_ERROR;
    }
    if ((size_t)size > CONFIG_SMART_HOME_MODEL_SECRETS_MAX_FILE_SIZE) {
        fclose(file);
        return AGENT_ERROR_LIMIT;
    }
    if (fseek(file, 0, SEEK_SET) != 0) {
        fclose(file);
        return AGENT_ERROR;
    }

    text = malloc((size_t)size + 1u);
    if (!text) {
        fclose(file);
        return AGENT_ERROR_NOMEM;
    }
    if (fread(text, 1u, (size_t)size, file) != (size_t)size) {
        fclose(file);
        secure_clear(text, (size_t)size + 1u);
        free(text);
        return AGENT_ERROR;
    }
    fclose(file);
    text[size] = '\0';
    *out_text = text;
    *out_size = (size_t)size;
    return AGENT_OK;
}

