    case HOME_ACTION_AGENT:
        if (ui->screen_chat) {
            lv_scr_load_anim(ui->screen_chat, LV_SCR_LOAD_ANIM_MOVE_LEFT,
                              180, 0, false);
        }
        break;
    default:
        break;
    }
}

