  status->init_status = smart_home_wifi_connect();
  if (status->init_status < 0)
    {
      syslog(LOG_WARNING, "Network: WiFi auto-connect failed: %d\n",
             status->init_status);
    }

  return smart_home_network_probe(status);
#endif
}

