1149	static int esp_hosted_transport_handle_sta_link_event(
1150	  FAR const uint8_t *payload, size_t payload_length, bool up)
1151	{
1152	  uint64_t key;
1153	  uint64_t value;
1154	  size_t offset = 0;
1155	  int result = OK;
1156	  int ret;
1157	
1158	  /* Rpc_Event_StaConnected and Rpc_Event_StaDisconnected both carry the
1159	   * operation result in protobuf field 1.  The connected/disconnected
1160	   * detail is field 2 and is intentionally skipped: only the association
1161	   * state belongs to the NuttX data-plane adapter.
1162	   */
1163	
1164	  while (offset < payload_length)
1165	    {
1166	      ret = esp_hosted_transport_get_varint(payload, payload_length, &offset,
1167	                                            &key);
1168	      if (ret < 0)
1169	        {
1170	          return ret;
1171	        }
1172	
1173	      if ((key >> 3) == 1)
1174	        {
1175	          if ((key & 7) != 0)
1176	            {
1177	              return -EPROTO;
1178	            }
1179	
1180	          ret = esp_hosted_transport_get_varint(payload, payload_length,
1181	                                                &offset, &value);
1182	          if (ret < 0)
1183	            {
1184	              return ret;
1185	            }
1186	
1187	          result = (int32_t)value;
1188	          continue;
1189	        }
1190	
1191	      ret = esp_hosted_transport_skip_field(payload, payload_length, &offset,
1192	                                            key & 7);
1193	      if (ret < 0)
1194	        {
1195	          return ret;
1196	        }
1197	    }
1198	
1199	  if (result != OK)
1200	    {
1201	      syslog(LOG_WARNING,
1202	             "WARNING: ESP-Hosted C6 STA %s event result=%d ignored\n",
1203	             up ? "connected" : "disconnected", result);
1204	      return OK;
1205	    }
1206	
1207	#ifdef CONFIG_ESPRESSIF_HOSTED_WLAN
1208	  esp_hosted_wlan_set_link(up);
1209	#endif
1210	
1211	  syslog(LOG_INFO, "INFO: ESP-Hosted C6 STA %s; wlan0 carrier %s\n",
1212	         up ? "connected" : "disconnected", up ? "on" : "off");
1213	  return OK;
1214	}
