 161	
 162	static int esp_hosted_wlan_transmit(FAR struct netdev_lowerhalf_s *dev,
 163	                                    FAR netpkt_t *pkt)
 164	{
 165	  FAR struct esp_hosted_wlan_s *priv =
 166	    (FAR struct esp_hosted_wlan_s *)dev;
 167	  unsigned int length;
 168	  irqstate_t flags;
 169	  bool link_up;
 170	  int ret;
 171	
 172	  flags = spin_lock_irqsave(&priv->rx_lock);
 173	  link_up = priv->ifup && priv->link_up;
 174	  spin_unlock_irqrestore(&priv->rx_lock, flags);
 175	  if (!link_up)
 176	    {
 177	      return -ENETDOWN;
 178	    }
 179	
 180	  length = netpkt_getdatalen(dev, pkt);
 181	  if (length == 0 || length > sizeof(priv->tx_buffer))
 182	    {
 183	      return -EMSGSIZE;
 184	    }
 185	
 186	  ret = netpkt_copyout(dev, priv->tx_buffer, pkt, length, 0);
 187	  if (ret < 0)
 188	    {
 189	      return ret;
 190	    }
 191	
 192	  ret = esp_hosted_transport_send_wlan(priv->transport, priv->tx_buffer,
 193	                                        length);
 194	  if (ret < 0)
 195	    {
 196	      return ret;
 197	    }
 198	
 199	  netpkt_free(dev, pkt, NETPKT_TX);
 200	  netdev_lower_txdone(dev);
 201	  return OK;
 202	}
 203	
 204	static FAR netpkt_t *esp_hosted_wlan_receive(
 205	  FAR struct netdev_lowerhalf_s *dev)
 206	{
 207	  FAR struct esp_hosted_wlan_s *priv =
 208	    (FAR struct esp_hosted_wlan_s *)dev;
 209	  FAR netpkt_t *pkt;
 210	  irqstate_t flags;
 211	
 212	  flags = spin_lock_irqsave(&priv->rx_lock);
 213	  pkt = netpkt_remove_queue(&priv->rx_queue);
 214	  spin_unlock_irqrestore(&priv->rx_lock, flags);
 215	  return pkt;
 216	}
 217	
 218	static void esp_hosted_wlan_reclaim(FAR struct netdev_lowerhalf_s *dev)
 219	{
 220	  (void)dev;
 221	}
 222	
 223	static int esp_hosted_wlan_rx(FAR void *arg, FAR const uint8_t *data,
 224	                              size_t length)
 225	{
 226	  FAR struct esp_hosted_wlan_s *priv = arg;
 227	  FAR netpkt_t *pkt;
 228	  irqstate_t flags;
 229	  int ret;
 230	
 231	  if (length < 14 || length > CONFIG_NET_ETH_PKTSIZE)
 232	    {
 233	      syslog(LOG_WARNING,
 234	             "WARNING: ESP-Hosted C6 RX: invalid station frame bytes=%u\n",
 235	             (unsigned int)length);
 236	      NETDEV_RXDROPPED(&priv->dev.netdev);
 237	      return OK;
 238	    }
 239	
 240	  flags = spin_lock_irqsave(&priv->rx_lock);
 241	  if (!priv->ifup || !priv->link_up)
 242	    {
 243	      spin_unlock_irqrestore(&priv->rx_lock, flags);
 244	      NETDEV_RXDROPPED(&priv->dev.netdev);
 245	      return OK;
 246	    }
 247	
 248	  spin_unlock_irqrestore(&priv->rx_lock, flags);
 249	  pkt = netpkt_alloc(&priv->dev, NETPKT_RX);
 250	  if (pkt == NULL)
 251	    {
 252	      syslog(LOG_WARNING, "WARNING: ESP-Hosted C6 RX: no packet buffer\n");
 253	      NETDEV_RXDROPPED(&priv->dev.netdev);
 254	      return OK;
 255	    }
 256	
 257	  ret = netpkt_copyin(&priv->dev, pkt, data, length, 0);
 258	  if (ret < 0)
 259	    {
 260	      netpkt_free(&priv->dev, pkt, NETPKT_RX);
 261	      NETDEV_RXDROPPED(&priv->dev.netdev);
 262	      return OK;
 263	    }
 264	
 265	  flags = spin_lock_irqsave(&priv->rx_lock);
 266	  if (!priv->ifup || !priv->link_up)
 267	    {
 268	      spin_unlock_irqrestore(&priv->rx_lock, flags);
 269	      netpkt_free(&priv->dev, pkt, NETPKT_RX);
 270	      return OK;
 271	    }
 272	
 273	  ret = netpkt_tryadd_queue(pkt, &priv->rx_queue);
 274	  spin_unlock_irqrestore(&priv->rx_lock, flags);
 275	  if (ret < 0)
 276	    {
 277	      netpkt_free(&priv->dev, pkt, NETPKT_RX);
 278	      NETDEV_RXDROPPED(&priv->dev.netdev);
 279	      return OK;
 280	    }
 281	
 282	  netdev_lower_rxready(&priv->dev);
 283	  return OK;
 284	}
