   230	     * 12/13 -> 14, 14 -> 16, 16/18 -> 18, 20/22 -> 24, 28+ -> 32. */
   231	    if (size <= 13 && g_style.font_14) {
   232	        return g_style.font_14;
   233	    }
   234	    if (size <= 15 && g_style.font_16) {
   235	        return g_style.font_16;
