static const char *const g_nav_titles[SMART_HOME_TAB_COUNT] = {
    "首页", "设备", "聊天", "安防", "更多"
};

static const char *const g_nav_icons[SMART_HOME_TAB_COUNT] = {
    ICON_NAV_HOME, ICON_NAV_DEVICES, ICON_NAV_CHAT, ICON_NAV_SECURITY,
