+static void esp_hosted_wlan_note_dhcp_tx(FAR struct esp_hosted_wlan_s *priv,
+                                          bool dhcp, bool error)
+{
+  irqstate_t flags = spin_lock_irqsave(&priv->rx_lock);
+
+  priv->dhcp_tx_frames++;
+  if (dhcp)
