+      usleep(SMART_HOME_NETWORK_LINK_POLL_MS * 1000);
+      timeout_ms -= SMART_HOME_NETWORK_LINK_POLL_MS;
+    }
+
+  return smart_home_network_link_up(ifname) ? OK : -ETIMEDOUT;
