config ESPRESSIF_DMA
	bool "General DMA (GDMA)"
	default n
	select ARCH_DMA

config ESPRESSIF_LDO
	bool "LDO regulator support"
	default n
	---help---
		Expose the ESP32-P4 internal LDO reservation API to chip and board
		drivers.  A board must still select the correct LDO channel and voltage
		for its external hardware.

menuconfig ESPRESSIF_MIPI_DSI
	bool "MIPI DSI host controller"
	depends on ESP32P4_REV_MIN_301
	default n
	select DRIVERS_VIDEO
	select ESPRESSIF_LDO
	select MIPI_DSI
	---help---
		Enable the ESP32-P4 MIPI DSI command-mode host adapter.  The ESP32-P4
		has one host and supports one or two data lanes.  Video/DPI transfer is
		configured by a board-level display adapter.

config ESPRESSIF_MIPI_CSI
	bool "MIPI CSI host controller"
	depends on ESP32P4_REV_MIN_301
	default n
	select ESPRESSIF_LDO
	select ESPRESSIF_ISP
	---help---
		Enable the ESP32-P4 MIPI CSI receiver Host, Bridge and DW-GDMA
		primitive. The receiver acquires its D-PHY LDO using the board-supplied
		profile. Sensor reset, MCLK and SCCB configuration remain board
		responsibilities.

config ESPRESSIF_ISP
	bool "ESP32-P4 image signal processor"
	depends on ESPRESSIF_MIPI_CSI
	default n

config ESPRESSIF_MIPI_CSI_VIDEO
	bool "MIPI CSI V4L2 data adapter"
	depends on ESPRESSIF_ISP && DRIVERS_VIDEO && VIDEO_STREAM
	select SCHED_HPWORK
	default n

if ESPRESSIF_MIPI_DSI

config ESPRESSIF_MIPI_DSI_TIMEOUT_MS
	int "MIPI DSI command polling timeout (ms)"
	default 100
	range 1 1000
	---help---
		Maximum time spent waiting for a command FIFO or PHY PLL operation.
		The host never uses an unbounded busy-wait loop.

config ESPRESSIF_MIPI_DSI_VIDEO
	bool "MIPI DSI DPI video mode"
	default n
	help
		Enable the ESP32-P4 MIPI DSI DPI video-mode support.  The Host
		pattern path is suitable for register-only diagnostics.  Select the
		DMA scanout option when a board needs a real pixel producer.

config ESPRESSIF_MIPI_DSI_VIDEO_DMA
	bool "MIPI DSI DPI DMA scanout"
	depends on ESPRESSIF_SPIRAM && ESPRESSIF_SPIRAM_USER_HEAP
	default n
	help
		Enable the DW-GDMA scanout path from a caller-owned RGB565 or RGB888
		frame buffer in the NuttX user PSRAM heap to the P4 MIPI-DSI Bridge.
		This is intended for board display bring-up and later framebuffer/LVGL
		integration; it does not create a generic NuttX framebuffer device by
		itself.

config ESPRESSIF_MIPI_DSI_DPI_PANEL
	bool "MIPI DSI DPI panel lifecycle adapter"
	depends on ESPRESSIF_MIPI_DSI_VIDEO_DMA
	default y
	---help---
		Enable the single-frame-buffer DPI panel lifecycle adapter.  It owns
		frame-buffer allocation, full-frame draw submission, cache clean and
		the DMA scanout lifetime, following the ESP-IDF DPI panel sequence.
		It does not register a generic NuttX framebuffer device.

endif # ESPRESSIF_MIPI_DSI

config ESPRESSIF_EFUSE
	bool "E-Fuse support"
	select EFUSE
	default n
	---help---
		Enable efuse support.

#  define ESP_MIPI_DSI_PHY_PLLREF_CLK_SRC \
  MIPI_DSI_PHY_PLLREF_CLK_SRC_DEFAULT
#else
#  define ESP_MIPI_DSI_PHY_PLLREF_CLK_SRC \
  MIPI_DSI_PHY_PLLREF_CLK_SRC_DEFAULT_LEGACY
#endif

