    }

  required_bytes = (size_t)config->hactive * config->vactive *
                   bytes_per_pixel;
  if (config->frame_buffer_bytes < required_bytes ||
      (required_bytes % ESP_MIPI_DSI_DMA_TRANSFER_WIDTH_BYTES) != 0)
    {
      return -EINVAL;
    }

  ret = nxmutex_lock(&priv->lock);
  if (ret < 0)
    {
      return ret;
