    {
      up_disable_irq(ESP_SOURCE2IRQ(ETS_CSI_BRIDGE_INTR_SOURCE));
      esp_teardown_irq(ETS_CSI_BRIDGE_INTR_SOURCE, priv->bridge_cpuint);
      priv->bridge_cpuint = -1;
    }

  syslog(LOG_INFO,
         "INFO: MIPI-CSI initialize: stage=complete frame_bytes=%zu\n",
         frame_bytes);

